928:
929:	/* If the device is really gone, cut short reset delays */
930:	if (us->pusb_dev->state == USB_STATE_NOTATTACHED) {
931:		set_bit(US_FLIDX_DISCONNECTING, &us->dflags);
932:		wake_up(&us->delay_wait);
